#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L, C;
    cin >> L >> C;

    vector<string> grid(L);
    for (int i = 0; i < L; i++) {
        cin >> grid[i];
    }

    int oi = -1, oj = -1;
    for (int i = 0; i < L; i++) {
        for (int j = 0; j < C; j++) {
            if (grid[i][j] == 'o') {
                oi = i;
                oj = j;
            }
        }
    }

    int pi = oi, pj = oj;
    int ci = -1, cj = -1;

    int di[4] = {-1, 1, 0, 0};
    int dj[4] = {0, 0, -1, 1};

    for (int d = 0; d < 4; d++) {
        int ni = oi + di[d];
        int nj = oj + dj[d];
        if (ni >= 0 && ni < L && nj >= 0 && nj < C && grid[ni][nj] == 'H') {
            ci = ni;
            cj = nj;
            break;
        }
    }

    while (true) {
        int nxt_i = -1, nxt_j = -1;
        int cnt = 0;

        for (int d = 0; d < 4; d++) {
            int ni = ci + di[d];
            int nj = cj + dj[d];

            if (ni < 0 || ni >= L || nj < 0 || nj >= C) continue;
            if (ni == pi && nj == pj) continue;
            if (grid[ni][nj] == 'H') {
                nxt_i = ni;
                nxt_j = nj;
                cnt++;
            }
        }

        if (cnt == 0) {
            cout << ci + 1 << ' ' << cj + 1 << '\n';
            break;
        }

        pi = ci;
        pj = cj;
        ci = nxt_i;
        cj = nxt_j;
    }

    return 0;
}
